 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, texture, vec4, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;

  const root = new THREE.Group();
  const card = new THREE.Group();
  root.add(card);

  const width = 2.0;
  const height = 1.25;

  const planeGeo = new THREE.PlaneGeometry(width, height);
  const planeMat = new MeshBasicNodeMaterial({ toneMapped: false });
  planeMat.colorNode = vec4(0.043, 0.043, 0.063, 1.0);

  const cardPlane = new THREE.Mesh(planeGeo, planeMat);
  card.add(cardPlane);

  const edgeGeo = new THREE.PlaneGeometry(width + 0.06, height + 0.06);
  const edgeMat = new MeshBasicNodeMaterial({ transparent: true, toneMapped: false });
  const edgeAlphaProxy = { value: 0.0 };
  const edgeAlphaUniform = uniform(0.0);
  edgeMat.colorNode = vec4(1.0, 0.165, 0.22, edgeAlphaUniform);
  const edgePlane = new THREE.Mesh(edgeGeo, edgeMat);
  edgePlane.position.z = -0.005;
  card.add(edgePlane);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      planeMat.colorNode = texture(tex).sample(uv());
      planeMat.needsUpdate = true;
    });
  }

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headline = items.find((item) => item.role === 'headline') || items[0];

  const label = ctx.fontAtlas.createText(headline?.text || 'Journal 2', {
    fontSize: headline?.typography?.fontSize || 39,
    color: '#e8ecf2',
    align: 'center',
  });
  label.position.set(0, 0, 0.012);
  card.add(label);

  const primitiveState = [];
  const primitives = config.cinematicPrimitives || [];
  for (const primitive of primitives) {
    if (ctx.primitives[primitive.name]) {
      const result = ctx.primitives[primitive.name](root, primitive.params || {});
      if (result) primitiveState.push(result);
    }
  }

  root.userData.handlers = {
    hover: (isHovering) => {
      gsap.to(card.position, {
        y: isHovering ? 0.15 : 0,
        duration: 0.3,
        ease: 'power2.out',
        overwrite: 'auto',
      });
      gsap.to(edgeAlphaProxy, {
        value: isHovering ? 1.0 : 0.0,
        duration: 0.2,
        overwrite: 'auto',
        onUpdate: () => {
          edgeAlphaUniform.value = edgeAlphaProxy.value;
        },
      });
    },
    click: () => {
      gsap.to(card.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        yoyo: true,
        repeat: 1,
        ease: 'back.out(2)',
        overwrite: 'auto',
        onComplete: () => {
          card.scale.set(1, 1, 1);
        },
      });
      ctx.emit('hub-journal.select', { card: 2, node: config.nodeId });
    },
  };

  root.userData.cleanup = () => {
    for (const result of primitiveState) {
      if (typeof result.cleanup === 'function') result.cleanup();
    }
    gsap.killTweensOf(card.position);
    gsap.killTweensOf(card.scale);
    gsap.killTweensOf(edgeAlphaProxy);
    planeMat.map?.dispose();
    planeMat.dispose();
    edgeMat.dispose();
    planeGeo.dispose();
    edgeGeo.dispose();
    card.remove(label);
    root.remove(card);
  };

  return root;
}
